INSERT INTO _staging_purchase_map (old_id, new_uuid)
SELECT op.old_id, p.id
FROM old_p op
JOIN purchases p ON p.supplier_id = op.supplier_uuid AND p.purchase_date = op.purchase_date AND p.subtotal = op.subtotal
